import {
    Table,
    GenericColumn,
    BooleanColumn,
    TranslatedTextColumn,
    StringColumn,
    ScriptColumn,
    IntegerColumn,
    ReferenceColumn,
    UserRolesColumn,
    JsonColumn,
    GuidColumn,
} from '../../db'

export const sp_instance = Table({
    allowWebServiceAccess: true,
    display: 'title',
    extends: 'sys_metadata',
    extensible: true,
    label: 'Instance',
    name: 'sp_instance',
    schema: {
        widget_parameters: GenericColumn({
            columnType: 'script_server',
            label: 'Additional options, JSON format',
            maxLength: 65000,
        }),
        css: GenericColumn({
            columnType: 'css',
            label: 'CSS',
            maxLength: 65000,
        }),
        preserve_placeholder_size: BooleanColumn({
            label: [
                {
                    hint: 'To avoid layout shift and retain the original placeholder, select the checkbox.',
                    label: 'Limit widget size to placeholder',
                    plural: 'Limit widget size to placeholders',
                    language: 'en',
                },
            ],
        }),
        placeholder_dimensions: JsonColumn({
            columnType: 'json',
            label: [
                {
                    hint: 'Placeholder Dimensions Configuration For Deferred widget',
                    label: 'Placeholder dimensions',
                    plural: 'Placeholder dimensions',
                    language: 'en',
                },
            ],
            maxLength: 4000,
        }),
        title: TranslatedTextColumn({
            label: 'Title',
            maxLength: 100,
        }),
        id: StringColumn({
            label: [
                {
                    hint: 'Identifier for $sp.getWidgetFromRectangle(id)',
                    label: 'ID',
                    plural: 'IDs',
                    language: 'en',
                },
            ],
            unique: true,
        }),
        async_load_device_type: StringColumn({
            choices: {
                desktop: {
                    label: 'Desktop',
                    sequence: 1,
                },
                tablet: {
                    label: 'Tablet',
                    sequence: 2,
                },
                mobile: {
                    label: 'Mobile',
                    sequence: 3,
                },
            },
            dropdown: 'dropdown_without_none',
            label: 'Device type',
            maxLength: 1024,
        }),
        url: StringColumn({
            label: 'HREF / URL',
            maxLength: 255,
        }),
        glyph: GenericColumn({
            columnType: 'glyphicon',
            label: 'Glyph',
        }),
        placeholder_dimensions_script: ScriptColumn({
            label: [
                {
                    hint: 'Placeholder configuration script',
                    label: 'Placeholder configuration script',
                    plural: 'Placeholder configuration scripts',
                    language: 'en',
                },
            ],
            maxLength: 4000,
        }),
        order: IntegerColumn({
            label: 'Order',
        }),
        advanced_placeholder_dimensions: BooleanColumn({
            label: [
                {
                    hint: 'Admin can dynamically define the height and width based on Instance option.',
                    label: 'Advance placeholder configuration',
                    plural: 'Advance placeholder configurations',
                    language: 'en',
                },
            ],
        }),
        async_load_trigger: StringColumn({
            choices: {
                viewport: {
                    label: 'Viewport | The widget will only load when it comes into view on the screen',
                    sequence: 1,
                },
                parallel: {
                    label: 'Parallel | The widget starts loading as soon as the page finishes loading',
                    sequence: 2,
                },
            },
            dropdown: 'dropdown_without_none',
            label: 'In which order do you want to load the widget?',
        }),
        class_name: StringColumn({
            label: [
                {
                    hint: 'Use with page or theme level CSS',
                    label: 'Bootstrap class name',
                    plural: 'Bootstrap class names',
                    language: 'en',
                },
            ],
        }),
        size: StringColumn({
            choices: {
                md: {
                    label: 'Medium',
                    sequence: 3,
                },
                lg: {
                    label: 'Large',
                    sequence: 4,
                },
                xs: {
                    label: 'Extra Small',
                    sequence: 1,
                },
                sm: {
                    label: 'Small',
                    sequence: 2,
                },
            },
            dropdown: 'dropdown_with_none',
            label: 'Bootstrap size',
        }),
        active: BooleanColumn({
            label: 'Active',
        }),
        sp_widget: ReferenceColumn({
            label: 'Widget',
            referenceTable: 'sp_widget',
            referenceQual:
                "javascript://'data_tableIN' + GlideDBObjectManager.getTables(current.getRecordClassName()).toArray().join()",
        }),
        color: GenericColumn({
            columnType: 'bootstrap_color',
            choices: {
                default: {
                    label: 'Default',
                    sequence: 1,
                },
                warning: {
                    label: 'Warning',
                    sequence: 5,
                },
                primary: {
                    label: 'Primary',
                    sequence: 2,
                },
                danger: {
                    label: 'Danger',
                    sequence: 6,
                },
                success: {
                    label: 'Success',
                    sequence: 3,
                },
                info: {
                    label: 'Info',
                    sequence: 4,
                },
            },
            dropdown: 'dropdown_with_none',
            label: 'Bootstrap color',
        }),
        placeholder_template: GenericColumn({
            columnType: 'xml',
            label: [
                {
                    hint: 'Placeholder template for Defer widget',
                    label: 'Placeholder template',
                    plural: 'Placeholder templates',
                    language: 'en',
                },
            ],
            maxLength: 65000,
        }),
        sys_id: GuidColumn({
            columnType: 'GUID',
            label: 'Sys ID',
            maxLength: 32,
            primary: true,
        }),
        async_load: BooleanColumn({
            label: [
                {
                    hint: 'Deferred loading will only be active when the checkbox is selected.',
                    label: 'Select the checkbox to defer load this widget',
                    plural: 'Select the checkbox to defer load this widgets',
                    language: 'en',
                },
            ],
        }),
        roles: UserRolesColumn({
            array: true,
            label: 'Roles',
        }),
        sp_column: ReferenceColumn({
            cascadeRule: 'delete',
            label: 'Column',
            referenceTable: 'sp_column',
        }),
        short_description: TranslatedTextColumn({
            label: 'Short description',
            maxLength: 255,
        }),
    },
})
